function nfStateCount(col, key, numsList) { const c = { col, key }; let n = 0; numsList.forEach(x => { if (nfStatePass(c, x)) n++; }); return n; }
/* ガード・ヒット・カウンター（有利・不利フレーム）は、格ゲーの言い方に合わせる：マイナスの数字では「以上」が「マイナスが多い（-11、-12…）」、「以下」が「マイナスが少ない」の意味。
   例）ガード -10以上 ＝ -10・-11・-12…（数の大小では ≤ -10）／ガード -10以下 ＝ -10・-9…・±0・+1…（数の大小では ≥ -10）。プラスの数字（0 を含む）は、そのまま数の大小。 */
function nfOp(c) {
  const k = NUM_COLMAP[c.col];
  if (k && k.adv && c.val < 0 && c.op !== "eq") return c.op === "le" ? "ge" : "le";
  return c.op;
}
function nfPass(nums) {
  const n = nums || {};
  if (!nfActiveStates().every(c => nfStatePass(c, n))) return false;
  return nfActiveConds().every(c => {
    const v = n[c.col];
    if (v === null || v === undefined) return false;
    const op = nfOp(c);
    return op === "le" ? v <= c.val : op === "ge" ? v >= c.val : v === c.val;
  });
}
/* list を並べ替えた新しい配列にする。並べ替えなしのときは ordOf（元の順）で並べる。数字のない技は最後、同じ数字は元の順 */
function nfSorted(list, numsOf, ordOf) {
  const col = NF.sortCol, dir = NF.sortDir === "desc" ? -1 : 1;
  return list.slice().sort((x, y) => {
    if (col) {
      const a = numsOf(x)[col], b = numsOf(y)[col];
      const an = a === null || a === undefined, bn = b === null || b === undefined;
      if (an !== bn) return an ? 1 : -1;
      if (!an && a !== b) return (a - b) * dir;
    }
    return ordOf(x) - ordOf(y);
  });
}
/* 条件に使っている項目のうち、このキャラの技に1つも数字が無いものの名前（「全体硬直」など。登録のないキャラへの案内に使う） */
function nfNoData(numsList) {
  const cols = new Set(nfActiveConds().map(c => c.col));
  if (NF.sortCol) cols.add(NF.sortCol);
  return [...cols].filter(id => !numsList.some(n => n && n[id] !== null && n[id] !== undefined)).map(id => NUM_COLMAP[id].label);
}
function nfBtnText(compact) {
  if (compact) return "絞り込み・並べ替え";   // 狭い画面用：条件があるかどうかは、ボタンの色と件数の表示で示す
  const parts = [];
  if (nfFilterOn()) parts.push("条件" + (nfActiveConds().length + nfActiveStates().length));
  if (nfSortOn()) parts.push("並べ替え中");
  return "絞り込み・並べ替え" + (parts.length ? "（" + parts.join("・") + "）" : "");
}
const NF_STATE_PRESETS = [
  { col: "hit",     key: "down",    label: "ヒット時 ダウン" },
  { col: "hit",     key: "noukemi", label: "ヒット時 受身不可" },
  { col: "hit",     key: "combo",   label: "ヒット時 コンボ始動" },
  { col: "counter", key: "down",    label: "カウンター時 ダウン" },
  { col: "counter", key: "float",   label: "カウンター時 浮き" },
  { col: "hit",     key: "wallS",   label: "ヒット時 壁やられ(強)" },
  { col: "hit",     key: "wallM",   label: "ヒット時 壁やられ(中)" }
];
const NF_OPS = [["le", "以下"], ["ge", "以上"], ["eq", "ちょうど"]];
const NF_PRESETS = [
  { col: "startup", op: "le", val: 15,  label: "発生 15F以下" },
  { col: "guard",   op: "ge", val: -10, label: "ガード -10F以上" },
  { col: "guard",   op: "ge", val: 0,   label: "ガード ±0F以上" },
  { col: "hit",     op: "ge", val: 10,  label: "ヒット +10F以上" },
  { col: "damage",  op: "ge", val: 30,  label: "ダメージ 30以上" }
];
function nfStatRefresh() { document.querySelectorAll(".nfp-stat").forEach(e => { e.textContent = NF.stat; }); }

/* ---------- 絞り込み・並べ替えのパネル（host の中に作る）。条件が変わるたびに onChange() を呼ぶ ---------- */
function nfPanel(host, onChange, getNums) {   // getNums() … いまのキャラの全部の技の数字（moveNums の結果の配列）。状態の選択肢に「該当数」を添えるのに使う
  host.classList.add("nfp");
  const h = (tag, cls, txt) => { const e = document.createElement(tag); if (cls) e.className = cls; if (txt != null) e.textContent = txt; return e; };
  const btn = (cls, txt, label) => { const b = h("button", cls, txt); b.type = "button"; if (label) b.setAttribute("aria-label", label); return b; };
  const unitOf = id => (NUM_COLMAP[id] && NUM_COLMAP[id].unit) || "";
  const syncClear = () => { const c = host.querySelector(".nfp-clear"); if (c) c.disabled = !(NF.conds.length || NF.states.length || nfSortOn()); };
  let chipSyncs = [];   // よく使う条件・状態のチップの「押されている」表示を、いまの条件に合わせる関数（render のたびに作り直す）
  const syncChips = () => chipSyncs.forEach(f => f());
  const fire = () => { syncClear(); syncChips(); if (onChange) onChange(); };

  function condRow(c) {
    const row = h("div", "nfp-row");
    const sc = h("select", "nfp-col"); sc.setAttribute("aria-label", "絞り込みの項目");
    NUM_COLS.forEach(k => { const o = h("option", "", k.label); o.value = k.id; sc.appendChild(o); });
    sc.value = c.col;
    const so = h("select", "nfp-op"); so.setAttribute("aria-label", "比べかた");
    NF_OPS.forEach(([v, t]) => { const o = h("option", "", t); o.value = v; so.appendChild(o); });
    so.value = c.op;
    const del = btn("nfp-del", "×", "この条件を削除");
    const val = h("span", "nfp-val");
    const sign = btn("nfp-st nfp-sign", "±", "プラス・マイナスを切り替え");
    const dec = btn("nfp-st", "-", "1減らす");
    const inp = h("input", "nfp-in");
    inp.type = "text"; inp.inputMode = "numeric"; inp.autocomplete = "off"; inp.placeholder = "数字"; inp.maxLength = 6;
    inp.setAttribute("aria-label", "比べる数字");
    inp.value = c.val === null ? "" : String(c.val);
    const inc = btn("nfp-st", "＋", "1増やす");
    const unit = h("span", "nfp-unit", unitOf(c.col));
    val.append(sign, dec, inp, inc, unit);
    const setVal = v => { c.val = v; inp.value = v === null ? "" : String(v); inp.setAttribute("aria-invalid", "false"); };
    inp.addEventListener("input", () => {
      const t = inp.value;
      c.val = parseNumInput(t);
      const bad = t.trim() !== "" && c.val === null && !/^[-−－+＋]$/.test(t.trim());
      inp.setAttribute("aria-invalid", String(bad));
      fire();
    });
    sign.onclick = () => {
      if (c.val !== null) setVal(c.val === 0 ? 0 : -c.val);
      else { const t = inp.value.trim(); inp.value = /^[-−－]/.test(t) ? t.slice(1) : "-" + t; c.val = parseNumInput(inp.value); }
      fire();
    };
    dec.onclick = () => { setVal((c.val === null ? 0 : c.val) - 1); fire(); };
    inc.onclick = () => { setVal((c.val === null ? 0 : c.val) + 1); fire(); };
    sc.onchange = () => { c.col = sc.value; unit.textContent = unitOf(c.col); fire(); };
    so.onchange = () => { c.op = so.value; fire(); };
    del.onclick = () => { NF.conds.splice(NF.conds.indexOf(c), 1); render(); fire(); };
    row.append(sc, so, val, del);
    return row;
  }

  /* ヒット・カウンター時の状態の行：［ヒット時▾］［状態▾（該当数つき）］［×］ */
  function stateRow(c) {
    const row = h("div", "nfp-srow");
    const sc = h("select", "nfp-scol"); sc.setAttribute("aria-label", "状態を調べる場面");
    ST_COLS.forEach(([v, t]) => { const o = h("option", "", t); o.value = v; sc.appendChild(o); });
    sc.value = c.col;
    const sk = h("select", "nfp-skey"); sk.setAttribute("aria-label", "状態");
    const fill = () => {
      const nums = getNums ? getNums() : null;
      sk.textContent = "";
      const o0 = h("option", "", "状態を選ぶ…"); o0.value = ""; sk.appendChild(o0);
      ST_GROUPS.forEach(g => {
        const og = h("optgroup"); og.label = g.label;
        g.items.forEach(([k, label]) => { const o = h("option", "", label + (nums ? "　" + nfStateCount(c.col, k, nums) + "技" : "")); o.value = k; og.appendChild(o); });
        sk.appendChild(og);
      });
      sk.value = c.key;
    };
    fill();
    const del = btn("nfp-sdel", "×", "この条件を削除");
    sc.onchange = () => { c.col = sc.value; fill(); fire(); };
    sk.onchange = () => { c.key = sk.value; fire(); };
    del.onclick = () => { NF.states.splice(NF.states.indexOf(c), 1); render(); fire(); };
    row.append(sc, sk, del);
    return row;
  }

  function render() {
    host.textContent = "";
    chipSyncs = [];
    // 絞り込み
    const s1 = h("section", "nfp-sec"); s1.dataset.sec = "num";
    s1.appendChild(h("h3", "nfp-h", "絞り込み（すべての条件に合う技だけを表示）"));
    const rows = h("div", "nfp-rows");
    NF.conds.forEach(c => rows.appendChild(condRow(c)));
    s1.appendChild(rows);
    const add = btn("nfp-add", "＋ 条件を追加");
    add.disabled = NF.conds.length >= NF_MAX;
    add.onclick = () => {
      NF.conds.push({ col: "startup", op: "le", val: null });
      render();
      const ins = host.querySelectorAll(".nfp-in"); if (ins.length) ins[ins.length - 1].focus();
      fire();
    };
    s1.appendChild(add);
    const pre = h("div", "nfp-pre");
    pre.appendChild(h("span", "nfp-prel", "よく使う条件"));
    NF_PRESETS.forEach(p => {
      const same = c => c.col === p.col && c.op === p.op && c.val === p.val;
      const b = btn("nfp-chip", p.label);
      const sync = () => b.setAttribute("aria-pressed", String(NF.conds.some(same)));
      sync(); chipSyncs.push(sync);
      b.onclick = () => {
        if (NF.conds.some(same)) NF.conds = NF.conds.filter(c => !same(c));            // 押されている → 外す（同じ条件が重なっていても全部外す）
        else {
          const dup = NF.conds.findIndex(c => c.col === p.col && c.op === p.op);        // 同じ項目・同じ比べかたの条件が別の数字で入っていれば、数字だけ置き換える（二重がけを防ぐ）
          const blank = NF.conds.findIndex(c => c.val === null);                        // 入力待ちの空の条件があれば、それを使う
          if (dup >= 0) NF.conds[dup].val = p.val;
          else if (blank >= 0) Object.assign(NF.conds[blank], { col: p.col, op: p.op, val: p.val });
          else if (NF.conds.length < NF_MAX) NF.conds.push({ col: p.col, op: p.op, val: p.val });
        }
        render(); fire();
      };
      pre.appendChild(b);
    });
    s1.appendChild(pre);
    host.appendChild(s1);
    // ヒット・カウンター時の状態（ダウン・浮き・受身・コンボ始動・倒れ方）
    const s3 = h("section", "nfp-sec"); s3.dataset.sec = "state";
    s3.appendChild(h("h3", "nfp-h", "ヒット・カウンター時の状態で絞り込み（ダウン別など）"));
    const srows = h("div", "nfp-rows");
    NF.states.forEach(c => srows.appendChild(stateRow(c)));
    s3.appendChild(srows);
    const sadd = btn("nfp-sadd", "＋ 状態の条件を追加");
    sadd.disabled = NF.states.length >= NF_MAX_ST;
    sadd.onclick = () => {
      NF.states.push({ col: "hit", key: "" });
      render();
      const ks = host.querySelectorAll(".nfp-skey"); if (ks.length) ks[ks.length - 1].focus();
      fire();
    };
    s3.appendChild(sadd);
    const spre = h("div", "nfp-pre");
    spre.appendChild(h("span", "nfp-prel", "よく使う状態"));
    NF_STATE_PRESETS.forEach(p => {
      const same = c => c.col === p.col && c.key === p.key;
      const b = btn("nfp-chip", p.label);
      const sync = () => b.setAttribute("aria-pressed", String(NF.states.some(same)));
      sync(); chipSyncs.push(sync);
      b.onclick = () => {
        if (NF.states.some(same)) NF.states = NF.states.filter(c => !same(c));
        else {
          const blank = NF.states.findIndex(c => !c.key);   // 選びかけの空の条件があれば、それを使う
          if (blank >= 0) Object.assign(NF.states[blank], { col: p.col, key: p.key });
          else if (NF.states.length < NF_MAX_ST) NF.states.push({ col: p.col, key: p.key });
        }
        render(); fire();
      };
      spre.appendChild(b);
    });
    s3.appendChild(spre);
    host.appendChild(s3);
    // 並べ替え
    const s2 = h("section", "nfp-sec"); s2.dataset.sec = "sort";
    s2.appendChild(h("h3", "nfp-h", "並べ替え"));
    const sr = h("div", "nfp-sort");
    const ss = h("select", "nfp-sc"); ss.setAttribute("aria-label", "並べ替えの項目");
    const o0 = h("option", "", "並べ替えなし（技表の順）"); o0.value = ""; ss.appendChild(o0);
    NUM_COLS.forEach(k => { const o = h("option", "", k.label); o.value = k.id; ss.appendChild(o); });
    ss.value = NF.sortCol;
    const sd = h("select", "nfp-sd"); sd.setAttribute("aria-label", "並べ替えの向き");
    [["asc", "小さい順"], ["desc", "大きい順"]].forEach(([v, t]) => { const o = h("option", "", t); o.value = v; sd.appendChild(o); });
    sd.value = NF.sortDir; sd.disabled = !NF.sortCol;
    ss.onchange = () => { NF.sortCol = ss.value; sd.disabled = !NF.sortCol; fire(); };
    sd.onchange = () => { NF.sortDir = sd.value; fire(); };
    sr.append(ss, sd);
    s2.appendChild(sr);
    host.appendChild(s2);
    // 件数・クリア
    const ft = h("div", "nfp-foot");
    const st = h("span", "nfp-stat"); st.setAttribute("role", "status"); st.setAttribute("aria-live", "polite"); st.textContent = NF.stat;
    const clr = btn("nfp-clear", "条件をすべてクリア");
    clr.disabled = !(NF.conds.length || NF.states.length || nfSortOn());
    clr.onclick = () => { NF.conds = []; NF.states = []; NF.sortCol = ""; NF.sortDir = "asc"; render(); fire(); };
    ft.append(st, clr);
    host.appendChild(ft);
    host.appendChild(h("p", "nfp-note", "ガード・ヒット・カウンターは、マイナスの数字では「以上」がマイナスの多いほう（例：ガード -10以上 ＝ -10・-11・-12…）、「以下」がマイナスの少ないほうです。ダメージ・削りは合計で比べます（複数の値は最初の数字）。ダウン・浮きなど数字のない技は、数値の条件を指定すると表示されなくなり、並べ替えでは最後になります（ダウンや浮きは「状態」の条件で絞り込めます）。答えが「D」とだけ登録されている技は、ダウンすることだけが分かっていて、倒れ方・受身の条件には該当しません。"));
  }
  render();
  return { render };
}

/* ---------- ワード検索（検索欄に数字だけではない文字を入れたとき） ----------
   対象は、技表に出ている文字すべて：技名・ふりがな・各項目（COLS：コマンド・攻撃判定・発生・ダメージ・ガード・ヒット・カウンター・壁やられ・ギミック・投げ抜け・削り・ホーミング・追尾方向・ジャンプ・しゃがみ・ヒート消費・全体硬直）の答え・
   コマンドの別表記・タグ（カプセル）と、その呼び名・メモ。「上」「中」「下」のような1文字でも、攻撃判定の文字に当たる。
   項目の境目をまたいで一致しないよう、項目の間に区切り（WS_SEP）を入れる（normQ は空白だけを消すので、区切りは残る）。
   数字だけの検索（数字ジャンプ）は、これまでどおり「技名・コマンドなど」の文字（q）を使う。ここで作る文字（qa）は、数字だけではない検索の絞り込みと色塗りに使う。
     wsCols(raw) … { 項目id: そろえた答えの文字 }（対象外の項目・答えの無い項目は入れない）。色塗りで、どのセルに当たったかを調べるのに使う
     wsHay(raw, memo) … 技1つぶんの、検索対象の文字すべて（そろえ済み） */
const WS_SEP = "\u001f";
function wsCols(raw) {
  const o = (raw && typeof raw === "object") ? raw : {}, a = o.a || {}, off = o.off || [], r = {};
  COLS.forEach(c => {
    if (off.indexOf(c.id) >= 0) return;
    let t = a[c.id]; if (t === null || t === undefined || t === "") return;
    t = String(t).replace(/\n/g, " ");
    if (c.id === "command" && a.ci) t += WS_SEP + String(a.ci).replace(/[.^]/g, "");   // コマンドの別表記（アイコン用の書き方）も対象
    r[c.id] = normQ(t);
  });
  return r;
}
function wsHay(raw, memo) {
  const o = (raw && typeof raw === "object") ? raw : {}, cols = wsCols(raw);
  return normQ([typeof raw === "string" ? raw : (o.name || ""), o.y || ""].concat(Object.keys(cols).map(id => cols[id]), [moveInfo(raw).kw, memo || ""]).join(WS_SEP));
}

/* ---------- 数字ジャンプ（検索欄に数字だけを入れたとき） ----------
   検索欄に「-10」「+8」「±0」「15」「15F」のような数字だけを入れると、技の一覧は絞り込まず、
   その数字が入っている項目（発生・ダメージ・ガード・ヒット・カウンター・全体硬直・削り）ごとに「ジャンプリンク」を検索欄の下に出す。
   押すとその項目が一致する最初の技へ移動して光り（パソコン版は該当のセルにも印）、もう一度押すと次の技へ進む（件数の表示が 2/5 のように変わる）。
   ・符号つき（-10・+8・±0）は、ガード・ヒット・カウンターだけが対象。符号なし（15）は、全部の項目が対象。
   ・数字の読み取りは numFrame / numSum と同じ（最初の数字）。表示中の技（ブックマーク・数値の絞り込みを通ったもの）だけを数える。
   ・符号なしの数字は、技名・コマンドなどに入っている場合（「66」など）も1つのリンクにする。
     「その文字を含む技だけ表示」のボタンで、今までどおりの文字での絞り込みに切り替えられる（検索の文字を変えると、切り替えは元に戻る）。
   ・数字だけでない検索（66RP・技名など）は、今までどおり絞り込みで、ジャンプリンクは出さない。
   組み込み：numJumpSetup({ host, cellOf(行の要素, 項目id)→セル or null, refilter() })／検索・絞り込みのたびに numMode(入力欄の文字) で
   「文字で絞り込むか」を決め、numJumpRefresh(入力欄の文字, [{ idx, nums, hay, vis }…]) を呼ぶ（rows は、文字の検索を除く絞り込みを通った技を、表示の順に並べたもの）。 */
const NJ = { qt: "", filter: false, pos: {}, sig: {}, cfg: null, off: {}, last: null };   // off：「✖」で解除した項目（NUM_COLS の id と "_t"）。検索の数字が変わるとリセット／last：直前の numJumpRefresh の引数（解除したときの作り直し用）
function numQuery(t) {
  const s = numClean(t).replace(/\s+/g, "").replace(/[FfＦｆ]$/, "");
  const m = /^([+\-±]?)(\d{1,4})$/.exec(s);
  if (!m) return null;
  const n = +m[2];
  return { sign: m[1], val: m[1] === "-" ? -n : n, text: m[1] + n };
}
function numMode(raw) {
  const nq = numQuery(raw), k = nq ? nq.text : "";
  if (NJ.qt !== k) { NJ.qt = k; NJ.filter = false; NJ.off = {}; }
  return { nq, textOn: !nq || NJ.filter };   // textOn：文字で技を絞り込むか
}
function numJumpSetup(cfg) { NJ.cfg = cfg; njStickInit(); }
function numFmt(c, v) { return c.adv ? (v > 0 ? "+" : v === 0 ? "±" : "") + v + "F" : v + (c.unit || ""); }
/* 「✖」のボタン（数字ジャンプの各項目の左端・「数字「〇〇」にジャンプ」の左端）。文字の「✖」ではなく線で描く（機種によって絵文字になって形が変わるのを避ける） */
function njXBtn(cls, label, title) {
  const x = document.createElement("button"); x.type = "button"; x.className = "njx" + (cls ? " " + cls : "");
  x.innerHTML = '<svg viewBox="0 0 12 12" aria-hidden="true" focusable="false"><path d="M2.5 2.5l7 7M9.5 2.5l-7 7"/></svg>';
  x.setAttribute("aria-label", label); x.title = title;
  return x;
}
/* 検索の一斉解除：検索欄を空にする（ジャンプの帯も色塗りも右端の目印も、文字での絞り込みも、すべて元に戻る） */
function njClearAll() {
  const q = document.getElementById("q"); if (!q) return;
  NJ.off = {}; NJ.filter = false;
  q.value = "";
  q.dispatchEvent(new Event("input", { bubbles: true }));
}
/* 1つの項目の解除：その項目のリンクと色塗りだけをなくす。最後の1つを解除したら、一斉解除と同じ */
function njDismiss(id) {
  const cfg = NJ.cfg, last = NJ.last; if (!cfg || !last) return;
  const wasFilter = NJ.filter;
  NJ.off[id] = true;
  if (id === "_t") NJ.filter = false;   // 文字での絞り込み中にその項目を解除したら、絞り込みも解く
  const n = numJumpRefresh(last.raw, last.rows);
  if (!n) { njClearAll(); return; }
  if (id === "_t" && wasFilter && cfg.refilter) cfg.refilter(); else shApply();   // 色塗り・右端の目印を、残った項目だけにする
  const f = cfg.host.querySelector(".njxall"); if (f) { try { f.focus({ preventScroll: true }); } catch (e) {} }
}
function numJumpRefresh(raw, rows) {
  const host = NJ.cfg && NJ.cfg.host; if (!host) return 0;
  const nq = numQuery(raw);
  njUnstick();   // 作り直す間は、いったん元の位置に戻す（終わったら njUpdate で貼りつけ直す）
  host.textContent = "";
  NJ.last = { raw, rows };
  if (!nq) { host.hidden = true; NJ.pos = {}; NJ.sig = {}; return 0; }
  const chips = [];
  NUM_COLS.filter(c => (!nq.sign || c.adv) && !NJ.off[c.id]).forEach(c => {   // 「✖」で解除した項目は出さない
    const hits = rows.filter(r => r.vis && r.nums && r.nums[c.id] === nq.val).map(r => r.idx);
    if (hits.length) chips.push({ id: c.id, label: c.label, val: numFmt(c, nq.val), hits });
  });
  const tq = normQ(raw);
  const th = tq && !NJ.off._t ? rows.filter(r => r.hay && r.hay.includes(tq)).map(r => r.idx) : [];
  if (th.length) chips.push({ id: "_t", label: "技名・コマンドなど", val: "「" + String(raw).trim() + "」を含む", hits: th });
  const head = document.createElement("div"); head.className = "njhead";
  const lb = document.createElement("span"); lb.className = "njlbl"; lb.textContent = "数字「" + nq.text + "」にジャンプ";
  const xa = njXBtn("njxall", "数字「" + nq.text + "」の検索をすべて解除", "検索をすべて解除（検索欄も空にします）");
  xa.addEventListener("click", njClearAll);
  head.append(xa, lb);
  const wrap = document.createElement("div"); wrap.className = "njchips";
  chips.forEach(ch => {
    const sig = nq.text + "|" + ch.hits.join(",");
    if (NJ.sig[ch.id] !== sig) { NJ.sig[ch.id] = sig; NJ.pos[ch.id] = -1; }
    const item = document.createElement("span"); item.className = "njitem";
    const xb = njXBtn("", ch.label + "の検索を解除", "「" + ch.label + "」の検索を解除（この項目のリンクと色塗りを消します）");
    xb.dataset.col = ch.id; xb.addEventListener("click", () => njDismiss(ch.id));
    const b = document.createElement("button"); b.type = "button"; b.className = "njchip"; b.dataset.col = ch.id;
    const t = document.createElement("span"); t.className = "njt"; t.textContent = ch.label;
    const v = document.createElement("span"); v.className = "njv"; v.textContent = ch.val;
    const n = document.createElement("span"); n.className = "njn"; n.textContent = ch.hits.length + "件";
    b.append(t, v, n);
    b.title = ch.label + "が " + ch.val + " の技：" + ch.hits.length + "件（押すと最初の技へ移動。もう一度押すと次の技へ）";
    b.setAttribute("aria-label", ch.label + " " + ch.val + "の技へ移動（" + ch.hits.length + "件）");
    b.addEventListener("click", () => {
      const p = ((NJ.pos[ch.id] === undefined ? -1 : NJ.pos[ch.id]) + 1) % ch.hits.length;
      NJ.pos[ch.id] = p;
      host.querySelectorAll(".njn").forEach(e => { if (e !== n) e.textContent = e.dataset.all; });
      n.textContent = ch.hits.length > 1 ? (p + 1) + "/" + ch.hits.length : "1件";
      jumpShow(ch.hits[p], 0, el => {
        document.querySelectorAll(".njflash").forEach(e => e.classList.remove("njflash"));
        const cell = ch.id !== "_t" && NJ.cfg.cellOf ? NJ.cfg.cellOf(el, ch.id) : null;
        if (cell) { void cell.offsetWidth; cell.classList.add("njflash"); clearTimeout(numJumpRefresh.t); numJumpRefresh.t = setTimeout(() => cell.classList.remove("njflash"), 1900); }
      });
    });
    n.dataset.all = n.textContent;
    item.append(xb, b);
    wrap.appendChild(item);
  });
  host.append(head, wrap);
  if (!chips.length) {
    const none = document.createElement("span"); none.className = "njnone";
    none.textContent = rows.length ? "「" + nq.text + "」にあたる数字は、このキャラの技に見つかりませんでした。" : "このキャラの技はまだ登録されていません。";
    wrap.appendChild(none);
  }
  if (th.length && NJ.cfg.refilter) {
    const f = document.createElement("button"); f.type = "button"; f.className = "njfilter";
    f.setAttribute("aria-pressed", String(NJ.filter));
    f.textContent = NJ.filter ? "文字での絞り込み：ON" : "「" + String(raw).trim() + "」を含む技だけ表示";
    f.title = "技名・コマンドなどに、この文字を含む技だけに絞り込みます";
    f.addEventListener("click", () => { NJ.filter = !NJ.filter; NJ.cfg.refilter(); });
    host.appendChild(f);
  }
  if (nq.sign) {
    const hint = document.createElement("p"); hint.className = "njhint";
    hint.textContent = "「-10以上」など範囲で探すときは、「絞り込み・並べ替え」を使ってください。";
    host.appendChild(hint);
  }
  host.hidden = false;
  njUpdate();
  return chips.length;
}

/* ============================================================
   追従する数字ジャンプ・検索のハイライト・サイドの目印（PC版・スマホ版で共通）
   ------------------------------------------------------------
   ◆追従：数字ジャンプの帯（NJ.cfg.host）が画面の上に出ていってしまったら、画面の上（NJ.cfg.top() のすぐ下）に1行にして貼りつける。
     元の場所には同じ高さの空きを残す（ページの長さが変わらない）。PC版は、表の見出しがその下に来るよう --njh を使う。
   ◆ハイライト：検索に一致した技名・ふりがな（黄色）、コマンド（枠）、数字のセル（黄色）、スマホ版は数字の印（バッジ）をカードの見出しに出す。
   ◆サイドの目印：ヒットした行の位置を画面の右端に並べる（Chromeのページ内検索と同じ）。押すとその行へ移動する。
   shSetup({ rows()→描画済みの行・カード, info(el)→{ idx, nums, hay, cmd }, cellOf(el, 項目id)→セル or null, badge: true なら数字の印をバッジで })
   shApply() … 検索・絞り込み・描画のたびに呼ぶ ============================================================ */
const NJS = { ph: null, h: 0 };
const njBarH = () => { const h = NJ.cfg && NJ.cfg.host; return (h && !h.hidden ? Math.round(parseFloat(getComputedStyle(document.documentElement).fontSize) * 2.75) : 0) + (typeof sqBarH === "function" ? sqBarH() : 0); };   // 貼りつけたときの高さ（数字ジャンプの帯：1行・2.75rem。追従する検索欄の帯もここに足す）
function njStickInit() {
  const host = NJ.cfg && NJ.cfg.host; if (!host || NJS.ph) return;
  NJS.ph = document.createElement("div"); NJS.ph.className = "njph"; NJS.ph.hidden = true; host.after(NJS.ph);
  let raf = 0;
  const later = () => { cancelAnimationFrame(raf); raf = requestAnimationFrame(njUpdate); };
  window.addEventListener("scroll", later, { passive: true });
  window.addEventListener("resize", later);
}
function njUnstick() {
  const host = NJ.cfg && NJ.cfg.host; if (!host || !NJS.ph) return;
  host.classList.remove("njfix"); ["top", "left", "width"].forEach(p => host.style.removeProperty(p));
  NJS.ph.hidden = true; NJS.ph.style.height = "";
  document.documentElement.style.removeProperty("--njh");
}
function njPlace() {
  const host = NJ.cfg.host, r = NJS.ph.getBoundingClientRect();
  host.style.top = (NJ.cfg.top ? NJ.cfg.top() : 0) + "px"; host.style.left = r.left + "px"; host.style.width = r.width + "px";
}
function njUpdate() {
  if (typeof sqUpdate === "function") sqUpdate();   // 検索欄の貼りつきを先に決める（数字ジャンプの帯は、その下に貼りつく）
  const host = NJ.cfg && NJ.cfg.host, ph = NJS.ph; if (!host || !ph) return;
  const stuck = host.classList.contains("njfix");
  if (host.hidden || !host.getClientRects().length && !stuck) { if (stuck) njUnstick(); return; }
  const top = NJ.cfg.top ? NJ.cfg.top() : 0;
  const t = (stuck ? ph : host).getBoundingClientRect().top;
  if (!stuck && t < top - 1) {
    ph.style.height = host.offsetHeight + "px"; ph.hidden = false;   // 先に空きを作ってから、帯を浮かせる
    host.classList.add("njfix"); njPlace();
    document.documentElement.style.setProperty("--njh", host.offsetHeight + "px");
  } else if (stuck && t >= top - 1) njUnstick();
  else if (stuck) njPlace();   // 幅・位置を合わせ直す
}

/* ============================================================
   追従する検索欄（PC版・スマホ版で共通）
   技表（スマホはカード）を下へスクロールして、検索欄が画面の上に出ていったら、検索欄そのもの（入力欄）を画面の上（SQ.cfg.top() のすぐ下）に貼りつける。
   ◆入力欄は動かさず（作り直さず）、position: fixed にするだけ。入力中の文字・カーソル・変換中の状態・スマホのキーボードは、貼りつく・戻るときも変わらない。
   ◆元の場所には同じ大きさの空き（.sqph）を残す（ページの長さが変わらない）。入力欄の後ろに、帯（#sqBar）を敷く。
   ◆貼りついた高さ --sqh を、PC版の表の見出し（thead th）・数字ジャンプの帯・ジャンプ先の位置が使う。
   sqSetup({ input, top()→貼りつける上端（スマホ版は上部バーの下）, host→帯の左右の範囲を決める枠（無ければ画面の幅いっぱい）, full: true なら画面の幅いっぱい, reserveR→右端に空ける幅（PC版のメニューボタン）, maxW→入力欄の最大幅 }) ============================================================ */
const SQ = { cfg: null, ph: null, bar: null, h: 0 };
const SQ_PAD = 6;
function sqSetup(cfg) {
  if (!cfg || !cfg.input || SQ.cfg) return;
  SQ.cfg = cfg;
  SQ.ph = document.createElement("div"); SQ.ph.className = "sqph"; SQ.ph.hidden = true;
  SQ.bar = document.createElement("div"); SQ.bar.id = "sqBar"; SQ.bar.hidden = true; SQ.bar.setAttribute("aria-hidden", "true");
  document.body.appendChild(SQ.bar);
  let raf = 0;
  const later = () => { cancelAnimationFrame(raf); raf = requestAnimationFrame(sqUpdate); };
  window.addEventListener("scroll", later, { passive: true });
  window.addEventListener("resize", () => { sqUnstick(); later(); });   // 大きさが変わったら、いったん戻して測り直す
  new MutationObserver(later).observe(document.documentElement, { attributes: true, attributeFilter: ["data-page", "data-theme"] });   // ページの切り替え・テーマの変更
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(later);
}
/* いま貼りついている帯の高さ（貼りついていなければ 0） */
const sqStuckH = () => (SQ.bar && !SQ.bar.hidden ? SQ.bar.offsetHeight : 0);
/* 貼りついたときの帯の高さ（まだ貼りついていなくても、検索欄が見えているページなら、その高さ）。ジャンプ先の位置の計算に使う */
const sqBarH = () => { const c = SQ.cfg; if (!c || !c.input.getClientRects().length) return 0; return Math.round((SQ.ph && !SQ.ph.hidden ? SQ.ph.offsetHeight : c.input.offsetHeight) + 2 * SQ_PAD); };
function sqUnstick() {
  const c = SQ.cfg; if (!c) return;
  c.input.classList.remove("sqfix"); ["top", "left", "width"].forEach(p => c.input.style.removeProperty(p));
  if (SQ.ph.parentNode) SQ.ph.remove();
  SQ.ph.hidden = true; SQ.ph.style.cssText = ""; SQ.bar.hidden = true;
  document.documentElement.style.removeProperty("--sqh");
}
function sqPlace() {
  const c = SQ.cfg, bar = SQ.bar, top = c.top ? c.top() : 0, cw = document.documentElement.clientWidth;
  const hr = !c.full && c.host ? c.host.getBoundingClientRect() : null;
  const left = hr ? hr.left : 0, right = hr ? hr.right : cw, h = SQ.h;
  bar.style.top = top + "px"; bar.style.left = left + "px"; bar.style.width = Math.max(0, right - left) + "px"; bar.style.height = h + "px";
  const pad = c.full ? 12 : 10, lim = Math.min(right, cw - (c.reserveR || 0));
  c.input.style.top = (top + SQ_PAD) + "px"; c.input.style.left = (left + pad) + "px";
  c.input.style.width = Math.max(120, Math.min(c.maxW || 99999, lim - left - pad * 2)) + "px";
}
function sqUpdate() {
  const c = SQ.cfg; if (!c) return;
  const input = c.input, ph = SQ.ph, stuck = input.classList.contains("sqfix");
  if (!input.getClientRects().length) { if (stuck) sqUnstick(); else SQ.bar.hidden = true; return; }   // 技表のページではないとき
  const top = c.top ? c.top() : 0;
  const t = (stuck ? ph : input).getBoundingClientRect().top;
  if (!stuck && t < top - 1) {
    const cs = getComputedStyle(input), r = input.getBoundingClientRect();
    ph.style.cssText = "display:block;box-sizing:border-box;flex:0 0 auto;width:" + r.width + "px;height:" + r.height + "px;margin:" + cs.margin + ";order:" + cs.order + ";";   // 先に同じ大きさの空きを作ってから、入力欄を浮かせる
    ph.hidden = false; input.before(ph);
    SQ.h = Math.round(r.height + 2 * SQ_PAD);
    input.classList.add("sqfix"); SQ.bar.hidden = false; sqPlace();
    document.documentElement.style.setProperty("--sqh", SQ.h + "px");
  } else if (stuck && t >= top - 1) sqUnstick();
  else if (stuck) sqPlace();   // 位置・幅を合わせ直す
}

const SH = { cfg: null, strip: null, hits: [], later: 0 };
const SH_SHORT = { startup: "発", damage: "ダ", guard: "ガ", hit: "ヒ", counter: "カ", recovery: "硬", chip: "削" };
function shSetup(cfg) {
  SH.cfg = cfg;
  const strip = document.createElement("div"); strip.id = "shMarks"; strip.hidden = true; strip.setAttribute("role", "group"); strip.setAttribute("aria-label", "検索でヒットした技の位置");
  document.body.appendChild(strip); SH.strip = strip;
  const later = () => { clearTimeout(SH.later); SH.later = setTimeout(shMarkers, 200); };
  window.addEventListener("resize", later);
  document.addEventListener("click", () => { if (SH.hits.length) later(); });   // カードの開閉・表示項目の切り替えなどで高さが変わったら、目印の位置を測り直す
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(later);
}
/* 全角・空白をそろえた文字（normQ と同じ）と、元の文字の位置の対応 */
function shNormChars(s) {
  const out = [];
  for (let i = 0; i < s.length; i++) {
    const n = normQ(s[i]);   // 検索側と同じそろえ方（スマホ版は、カタカナ→ひらがなも含む）
    for (let j = 0; j < n.length; j++) out.push({ c: n[j], i });
  }
  return out;
}
/* 要素の文字のうち、検索の文字に一致する所を <mark> で囲む（一致が無ければ何もしない） */
function shMarkText(el, tq) {
  const orig = el.dataset.shOrig !== undefined ? el.dataset.shOrig : el.textContent;
  const ch = shNormChars(orig), ns = ch.map(x => x.c).join("");
  const ranges = []; let from = 0;
  for (;;) { const p = ns.indexOf(tq, from); if (p < 0) break; ranges.push([ch[p].i, ch[p + tq.length - 1].i + 1]); from = p + tq.length; }
  if (!ranges.length) return false;
  el.dataset.shOrig = orig;
  const frag = document.createDocumentFragment(); let pos = 0;
  ranges.forEach(([a, b]) => {
    if (a > pos) frag.appendChild(document.createTextNode(orig.slice(pos, a)));
    const m = document.createElement("mark"); m.className = "shl"; m.textContent = orig.slice(a, b); frag.appendChild(m); pos = b;
  });
  if (pos < orig.length) frag.appendChild(document.createTextNode(orig.slice(pos)));
  el.textContent = ""; el.appendChild(frag);
  return true;
}
function shClear() {
  document.querySelectorAll("[data-sh-orig]").forEach(e => { e.textContent = e.dataset.shOrig; delete e.dataset.shOrig; });
  document.querySelectorAll(".sh-hit, .nhit, .whit, .shl-cmd").forEach(e => e.classList.remove("sh-hit", "nhit", "whit", "shl-cmd"));
  document.querySelectorAll(".nhb").forEach(e => e.remove());
}
function shBadge(el, ids, nq) {
  const nm = el.querySelector(".head .nm, td.name .nm"); if (!nm) return;
  let mi = nm.querySelector(".minfo");
  if (!mi) { mi = document.createElement("span"); mi.className = "minfo"; nm.appendChild(mi); }
  ids.forEach(id => {
    const c = NUM_COLMAP[id], b = document.createElement("span");
    b.className = "nhb"; b.textContent = SH_SHORT[id] + numFmt(c, nq.val);
    b.title = c.label + "が " + numFmt(c, nq.val); b.setAttribute("aria-label", b.title);
    mi.appendChild(b);
  });
}
function shApply() {
  const cfg = SH.cfg; if (!cfg) return;
  shClear();
  const raw = document.getElementById("q").value || "";
  const tq = normQ(raw), nq = numQuery(raw);
  SH.hits = [];
  if (tq) {
    cfg.rows().forEach(el => {
      const f = cfg.info(el); if (!f) return;
      const numIds = nq ? NUM_COLS.filter(c => !NJ.off[c.id] && (!nq.sign || c.adv) && f.nums && f.nums[c.id] === nq.val).map(c => c.id) : [];   // 「✖」で解除した項目は、色を塗らない
      const hay = nq ? f.hay : (f.qa || f.hay);   // 数字だけの検索は「技名・コマンドなど」の文字／それ以外（ワード検索）は技表の文字すべて
      const textHit = !!hay && hay.includes(tq) && !(nq && NJ.off._t);
      if (!numIds.length && !textHit) return;
      let seen = false;   // 画面に見える印を付けられたか
      if (textHit) {
        el.querySelectorAll(".nt, .yomi").forEach(n => { if (shMarkText(n, tq)) seen = true; });
        const ce = el.querySelector(".mcmd, .cmdtxt");
        if (ce && !ce.classList.contains("off") && !ce.hidden && f.cmd && f.cmd.includes(tq)) { ce.classList.add("shl-cmd"); seen = true; }   // コマンドは、アイコンの並びごと枠で囲む
        if (!nq) {   // ワード検索：攻撃判定・タグの文字と、当たった項目のセル（開いていないカードのセルは無いので、その場合は行の印だけ）
          el.querySelectorAll(".atk, .tg").forEach(n => { if (n.getClientRects().length && shMarkText(n, tq)) seen = true; });
          const cols = f.cols || {};
          Object.keys(cols).forEach(id => {
            if (!cols[id].includes(tq)) return;
            const c = cfg.cellOf && cfg.cellOf(el, id); if (!c) return;
            c.classList.add("whit"); seen = true;
            c.querySelectorAll(".ans").forEach(a => { if (!a.children.length) shMarkText(a, tq); else if (a.classList.contains("st2")) a.querySelectorAll(".a1, .a2").forEach(x => { if (!x.children.length) shMarkText(x, tq); }); });   // 答えを全表示のときは、答えの中の当たった文字を黄色に（アイコンなどの入った答えは、セルの色だけ）
          });
        }
      }
      numIds.forEach(id => { const c = cfg.cellOf && cfg.cellOf(el, id); if (c) { c.classList.add("nhit"); seen = true; } });
      if (cfg.badge && numIds.length) shBadge(el, numIds, nq);
      if (numIds.length || !seen) el.classList.add("sh-hit");   // 数字の検索は絞り込まないので、ヒットした行に印を付ける。文字の検索でも、見える所に印が無い（読み・キーワードで一致した）行には印を付ける
      SH.hits.push({ el, idx: f.idx });
    });
  }
  shMarkers();
  clearTimeout(SH.later); SH.later = setTimeout(shMarkers, 400);   // 描画・収め直しが落ち着いてから、もう一度位置を測る
}
/* 右端の目印：ヒットした行の、ページ全体の中での位置（画面の高さに縮めて並べる）。近い位置は1本にまとめる */
function shMarkers() {
  const strip = SH.strip; if (!strip) return;
  strip.textContent = "";
  const H0 = Math.max(document.documentElement.scrollHeight, 1), vh = window.innerHeight;
  /* 行の位置（0〜1）：ふつうはページ全体の長さに対する位置。表が枠の中で縦にスクロールするとき（PC版・幅1000px以下）は、枠の中身の長さに対する位置（ページは短いので、ページの長さでは測れない） */
  const pts = SH.hits.filter(h => h.el.isConnected && h.el.getClientRects().length).map(h => {
    const r = h.el.getBoundingClientRect(), sc = typeof jumpScroller === "function" ? jumpScroller(h.el) : null;
    const y = sc ? r.top - sc.getBoundingClientRect().top + sc.scrollTop + r.height / 2 : r.top + window.pageYOffset + r.height / 2;
    return { f: y / (sc ? Math.max(sc.scrollHeight, 1) : H0), idx: h.idx };
  }).sort((a, b) => a.f - b.f);
  if (!pts.length) { strip.hidden = true; return; }
  const ticks = []; let last = -99;
  pts.forEach(p => {
    const k = Math.round(p.f * vh);
    if (k - last >= 4 || !ticks.length) { ticks.push({ k, n: 1, idx: p.idx }); last = k; } else ticks[ticks.length - 1].n++;
  });
  const total = pts.length;
  ticks.forEach(t => {
    const b = document.createElement("button"); b.type = "button"; b.className = "shtick"; b.style.top = Math.max(0, t.k - 1) + "px";
    b.title = "ヒットした技へ移動" + (t.n > 1 ? "（このあたりに" + t.n + "件）" : "") + "／全" + total + "件";
    b.setAttribute("aria-label", b.title);
    b.addEventListener("click", () => { jumpShow(t.idx, 0); });
    strip.appendChild(b);
  });
  strip.hidden = false;
}
/*RVNUMJS-END*/
